package studio.solocamera;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.*;import android.os.*;import androidx.media3.common.*;import androidx.media3.transformer.*;import java.io.*;import java.util.concurrent.*;import java.lang.reflect.*;
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
final class ProfessionPresetChecks {
 interface Action{void run()throws Exception;}
 static void check(boolean v,String m){if(!v)throw new AssertionError(m);}
 static void ui(Instrumentation h,Action a){Throwable[] error={null};h.runOnMainSync(()->{try{a.run();}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new RuntimeException(error[0]);}
 static void stage(Instrumentation h,String text){Bundle b=new Bundle();b.putString("stage",text);h.sendStatus(0,b);}
 static void image(File d,String n,Bitmap b)throws Exception{try(FileOutputStream o=new FileOutputStream(new File(d,n))){b.compress(Bitmap.CompressFormat.PNG,100,o);}}
 static void render(Instrumentation h,EditorProject p,File f)throws Exception{f.delete();CountDownLatch done=new CountDownLatch(1);Throwable[] error={null};Transformer[] task={null};ui(h,()->{task[0]=new Transformer.Builder(h.getTargetContext()).setVideoMimeType(MimeTypes.VIDEO_H264).setAudioMimeType(MimeTypes.AUDIO_AAC).addListener(new Transformer.Listener(){public void onCompleted(Composition c,ExportResult r){done.countDown();}public void onError(Composition c,ExportResult r,ExportException e){error[0]=e;done.countDown();}}).build();task[0].start(EditorComposition.build(p),f.getAbsolutePath());});if(!done.await(60,TimeUnit.SECONDS)){ui(h,()->task[0].cancel());throw new AssertionError("Preset export timeout");}if(error[0]!=null)throw new RuntimeException(error[0]);}
 static void call(Object o,String n)throws Exception{Method m=o.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(o);}static void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
 static void click(Instrumentation h,String text)throws Exception{for(int tries=0;tries<10;tries++){var root=h.getUiAutomation().getRootInActiveWindow();if(root!=null)for(var n:root.findAccessibilityNodeInfosByText(text)){var p=n;while(p!=null&&!p.isClickable())p=p.getParent();if(p!=null){p.performAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SHOW_ON_SCREEN.getId());Thread.sleep(150);if(p.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK)){Thread.sleep(250);return;}}}Thread.sleep(200);}throw new AssertionError("Missing "+text);}
 static void run(Instrumentation h,Bundle result)throws Exception{
  EditorFonts.init(h.getTargetContext());File dir=new File(h.getTargetContext().getCacheDir(),"profession-preset-qa");dir.mkdirs();stage(h,"Rendering 50 profession designs in portrait and landscape");check(EditorTitlePresets.NAMES.length==138,"Preset count");
  for(int id=88;id<138;id++){EditorProject.Clip c=EditorTitlePresets.create(id,4000),copy=EditorProject.Clip.from(c.json());check(copy.titleParticles&&copy.titleSound&&copy.titleGlow==.8&&copy.titleSoundVolume==.30&&copy.keys.isEmpty(),"FX persistence "+id);check(EditorTitlePresets.group(id)==7,"Group "+id);for(int[] size:new int[][]{{640,360},{360,640}}){Bitmap b=EditorText.bitmap(copy,size[0],size[1]);check(b.getWidth()<=size[0]&&b.getHeight()<=size[1],"Size "+id);image(dir,"preset-"+id+"-"+size[0]+".png",b);b.recycle();}EditorTitleAnimation a=new EditorTitleAnimation(c,360,640);try{Bitmap one=a.frame(1300,4000).copy(Bitmap.Config.ARGB_8888,false),two=a.frame(2100,4000);check(!one.sameAs(two),"Moving FX missing "+id);one.recycle();}finally{a.release();}File sound=EditorTitleSounds.file(c);check(sound.length()==45644,"WAV size "+id);try(RandomAccessFile wav=new RandomAccessFile(sound,"r")){check(wav.readInt()==0x52494646,"WAV header");wav.seek(44);long energy=0;while(wav.getFilePointer()<wav.length())energy+=Math.abs(Short.reverseBytes(wav.readShort()));check(energy>100000,"Sound silent");}c.titleSound=false;check(!EditorTitleSounds.active(EditorProject.Clip.from(c.json())),"Mute persistence");}
  stage(h,"Exporting animated title and synchronized audio");EditorProject p=new EditorProject();p.id="66666666-6666-4666-8666-666666666651";p.name="Profession preset QA";p.aspect=2;p.height=720;EditorProject.Caption c=new EditorProject.Caption();c.type="Text";c.style=EditorTitlePresets.create(92,3000);c.at=1000;c.end=4000;p.captions.add(c);check(EditorTitleSounds.sequences(p).size()==1,"Sound sequence");File out=new File(dir,"profession.mp4");render(h,p,out);MediaMetadataRetriever m=new MediaMetadataRetriever();try{m.setDataSource(out.getAbsolutePath());check("yes".equals(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_AUDIO)),"Export missing sound");check("yes".equals(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_VIDEO)),"Export missing video");Bitmap b=m.getFrameAtTime(2300000,MediaMetadataRetriever.OPTION_CLOSEST);check(b!=null,"Export frame");image(dir,"export-frame.png",b);b.recycle();}finally{m.release();}float[] waveform=EditorWaveform.decode(out.getAbsolutePath(),4000);float early=0,accent=0;for(int i=0;i<waveform.length;i++){if(i<35)early=Math.max(early,waveform[i]);if(i>=48&&i<=95)accent=Math.max(accent,waveform[i]);}check(early<.1&&accent>.7,"Export accent not synchronized at one second: "+early+"/"+accent);c.at=2200;c.end=5200;check(EditorTitleSounds.sequences(p).size()==1,"Moved sound lost");c.style.titleSound=false;check(EditorTitleSounds.sequences(p).isEmpty(),"Muted sound exported");p.captions.clear();check(EditorTitleSounds.sequences(p).isEmpty(),"Deleted sound exported");
  stage(h,"Testing profession browser, live preview and sound controls");EditorActivity activity=(EditorActivity)h.startActivitySync(new Intent(h.getTargetContext(),EditorActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{ui(h,()->{set(activity,"project",p);set(activity,"editing",true);set(activity,"position",0L);call(activity,"showEditor");new EditorTitleLibrary(activity,1080,1920,(clip,duration)->{EditorProject.Caption item=new EditorProject.Caption();item.style=clip;item.type="Text";item.end=duration;p.captions.add(item);}).show(100);});Thread.sleep(700);Bitmap screen=h.getUiAutomation().takeScreenshot();image(dir,"browser.png",screen);screen.recycle();click(h,"Technology · Quantum circuit");Thread.sleep(500);click(h,"Preview animation + sound");Thread.sleep(1100);screen=h.getUiAutomation().takeScreenshot();image(dir,"customize.png",screen);screen.recycle();click(h,"Add to timeline");check(p.captions.size()==1&&p.captions.get(0).style.titleDesign==89,"Preset insertion");ui(h,()->{call(activity,"releasePlayer");EditorLivePreview live=new EditorLivePreview(activity,new EditorLivePreview.Listener(){public void frame(){}public void error(String message){throw new AssertionError(message);}});live.bind(p);live.seekTo(0);live.play();activity.addContentView(live,new android.view.ViewGroup.LayoutParams(300,500));set(activity,"livePreview",live);});Thread.sleep(1600);ui(h,()->{Field f=EditorActivity.class.getDeclaredField("livePreview");f.setAccessible(true);EditorLivePreview live=(EditorLivePreview)f.get(activity);check(live.position()>500,"Sound preview stalled");live.release();});result.putString("checks","PASS 50 designs x portrait/landscape, moving FX, JSON, 50 audible WAV accents, H264/AAC export, linked sound move/mute/delete, browser, customize and playing preview");}finally{ui(h,activity::finish);new File(h.getTargetContext().getFilesDir(),"edit-projects/"+p.id+".json").delete();}
 }
}
